SET search_path TO user_09;

CREATE TABLE "PRQAutomoviles"
(
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Color" VARCHAR(50) NOT NULL,
    "Anio" INTEGER NOT NULL,
    "Fabricante" VARCHAR(100) NOT NULL,
    "Tipo" VARCHAR(20) NOT NULL,
    CONSTRAINT "CK_PRQAutomoviles_Tipo"
        CHECK ("Tipo" IN ('Sedan', '4x4', 'Moto'))
);

CREATE TABLE "PRQParqueos"
(
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Provincia" VARCHAR(100) NOT NULL,
    "Nombre" VARCHAR(150) NOT NULL,
    "PrecioPorHora" NUMERIC(10,2) NOT NULL,
    CONSTRAINT "CK_PRQParqueos_Precio"
        CHECK ("PrecioPorHora" >= 0)
);

CREATE TABLE "PRQIngresos"
(
    "Consecutivo" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "IdParqueo" INTEGER NOT NULL REFERENCES "PRQParqueos"("Id"),
    "IdAutomovil" INTEGER NOT NULL REFERENCES "PRQAutomoviles"("Id"),
    "FechaHoraEntrada" TIMESTAMP NOT NULL,
    "FechaHoraSalida" TIMESTAMP NULL,
    CONSTRAINT "CK_PRQIngresos_Fechas"
        CHECK (
            "FechaHoraSalida" IS NULL
            OR "FechaHoraSalida" >= "FechaHoraEntrada"
        )
);

